'use client'

import React, { useMemo, useState } from 'react'
import { Activity, BarChart3, Bell, CalendarDays, ChevronDown, ChevronRight, ClipboardCheck, Edit3, FolderKanban, GitBranch, Home as HomeIcon, Menu, Plus, Search, Target, Users, X } from 'lucide-react'

function MapViewFinal() {
	const [selectedMonth, setSelectedMonth] = useState('Jul')
	const [expandedGroups, setExpandedGroups] = useState<string[]>([])
	const [expandedIndicators, setExpandedIndicators] = useState<string[]>([])
	const [hierarchy, setHierarchy] = useState(false)
	const [detail, setDetail] = useState<Indicator | null>(null)
	const value = (item: Indicator, target: boolean) => target ? (item.status === 'red' ? '95%' : item.status === 'yellow' ? '96%' : '100%') : (item.status === 'red' ? '91%' : item.status === 'yellow' ? '94%' : '100%')
	const toggle = (list: string[], code: string, setter: React.Dispatch<React.SetStateAction<string[]>>) => setter(list.includes(code) ? list.filter(value => value !== code) : [...list, code])
	const rowsFor = (code: string) => seed.filter(item => item.perspective === code && (!item.parent || expandedIndicators.includes(item.parent)))
	if (hierarchy) return <Screen title="Mapa de indicadores" subtitle="Relação entre indicadores estratégicos e seus desdobramentos."><div className="map-sheet-toolbar"><div className="map-mode"><button onClick={() => setHierarchy(false)}>Lista de indicadores</button><button className="selected">Mapa hierárquico</button></div></div><section className="hierarchy-map hierarchy-map-final"><div className="hierarchy-map-head"><span className="eyebrow">MAPA HIERÁRQUICO</span><h2>Relação entre indicadores</h2><p>Os indicadores filhos estão conectados ao seu indicador pai.</p></div><div className="hierarchy-flow">{seed.filter(item => !item.parent).map(parent => <div className="hierarchy-branch" key={parent.code}><button className={`hierarchy-node ${parent.status}`} onClick={() => setDetail(parent)}><b>{parent.name}</b><small>Real {value(parent, false)} · Meta {value(parent, true)}</small></button>{seed.filter(item => item.parent === parent.code).map(child => <div className="hierarchy-child-branch" key={child.code}><span className="hierarchy-connector"/><button className={`hierarchy-node child ${child.status}`} onClick={() => setDetail(child)}><b>{child.name}</b><small>Real {value(child, false)} · Meta {value(child, true)}</small></button></div>)}</div>)}</div></section>{detail && <IndicatorSide item={detail} onClose={() => setDetail(null)}/>}</Screen>
	return <Screen title="Mapa de indicadores" subtitle="Acompanhe Real, Meta, farol mensal e YTD por indicador."><div className="map-sheet-toolbar"><div className="map-mode"><button className="selected">Lista de indicadores</button><button onClick={() => setHierarchy(true)}>Mapa hierárquico</button></div><Btn primary><Plus size={15}/> Novo indicador</Btn></div><section className="map-sheet"><div className="map-sheet-head"><div><span className="eyebrow">PLANILHA / FAROL</span><h2>Indicadores da Unidade Gerencial</h2></div><span>Período selecionado: <b>{selectedMonth} 2026</b></span></div><div className="map-sheet-scroll"><table className="map-grid refined-map"><thead><tr><th>Indicador</th><th>Usuários</th><th>Real</th><th>Meta</th>{months.map(month => <th key={month} className={month === selectedMonth ? 'selected-month' : ''}><button className="month-button" onClick={() => setSelectedMonth(month)}>{month}</button></th>)}<th>YTD</th><th>Ações</th></tr></thead><tbody>{perspectives.map(([code, label, color]) => { const open = expandedGroups.includes(code); const group = rowsFor(code); return <React.Fragment key={code}><tr className="map-group"><th colSpan={18}><button className="group-toggle" onClick={() => toggle(expandedGroups, code, setExpandedGroups)}><span>{open ? '−' : '+'}</span><i style={{background:color}}/>{label}<small>({seed.filter(item => item.perspective === code).length})</small></button></th></tr>{open && group.map((item, index) => { const hasChildren = seed.some(child => child.parent === item.code); const expanded = expandedIndicators.includes(item.code); return <tr key={item.code}><td><div className="map-indicator-cell"><button className="indicator-expand" disabled={!hasChildren} onClick={() => toggle(expandedIndicators, item.code, setExpandedIndicators)}>{hasChildren ? (expanded ? '−' : '+') : '·'}</button><button className="map-indicator-link" onClick={() => setDetail(item)}><strong>{item.name}</strong><small>{item.code} · {item.owner}</small></button></div></td><td><AvatarStack names={item.viewers}/></td><td className="map-value">{value(item, false)}</td><td className="map-value">{value(item, true)}</td>{months.map((month, monthIndex) => <td className={`map-light ${month === selectedMonth ? 'selected-month' : ''}`} key={month}><span className={`traffic-symbol ${item.status === 'red' ? 'red' : item.status === 'yellow' || (index + monthIndex) % 5 === 3 ? 'yellow' : 'green'}`}>{item.status === 'red' ? '▲' : item.status === 'yellow' || (index + monthIndex) % 5 === 3 ? '■' : '●'}</span></td>)}<td className="map-ytd"><b>{value(item, false)}</b><small>meta {value(item, true)}</small></td><td><div className="map-actions"><button title="Visualizar" onClick={() => setDetail(item)}><Search size={13}/></button><button title="Editar"><Edit3 size={13}/></button></div></td></tr> })}</React.Fragment>})}</tbody></table></div></section>{detail && <IndicatorSide item={detail} onClose={() => setDetail(null)}/>}</Screen>
}

function MapViewInteractive() {
	const [selectedMonth, setSelectedMonth] = useState('Jul')
	const [expandedGroups, setExpandedGroups] = useState<string[]>([])
	const [mode, setMode] = useState<'lista' | 'hierarquia'>('lista')
	const [detail, setDetail] = useState<Indicator | null>(null)
	const getValue = (item: Indicator, kind: 'real' | 'target') => {
		const index = months.indexOf(selectedMonth)
		if (kind === 'target') return item.status === 'red' ? '95%' : item.status === 'yellow' ? '96%' : '100%'
		const values = item.status === 'red' ? ['89%', '91%', '92%', '90%', '88%', '91%', '91%', '87%', '90%', '92%', '91%', '89%'] : item.status === 'yellow' ? ['94%', '93%', '95%', '94%', '92%', '94%', '94%', '93%', '95%', '94%', '94%', '92%'] : ['100%', '98%', '101%', '100%', '99%', '100%', '100%', '100%', '102%', '100%', '100%', '99%']
		return values[index]
	}
	const shape = (item: Indicator, index: number) => item.status === 'red' ? 'red' : item.status === 'yellow' || index % 5 === 3 ? 'yellow' : 'green'
	const indicatorRows = (code: string) => seed.filter(item => item.perspective === code && (!item.parent || expandedGroups.includes(item.parent)))
	const hasChildren = (code: string) => seed.some(item => item.parent === code)
	return <Screen title="Mapa de indicadores" subtitle="Acompanhe Real, Meta, farol mensal e YTD por indicador.">
		<div className="map-sheet-toolbar"><div className="map-mode"><button className={mode === 'lista' ? 'selected' : ''} onClick={() => setMode('lista')}>Lista de indicadores</button><button className={mode === 'hierarquia' ? 'selected' : ''} onClick={() => setMode('hierarquia')}>Mapa hierárquico</button></div><Btn primary><Plus size={15}/> Novo indicador</Btn></div>
		{mode === 'hierarquia' ? <section className="hierarchy-map"><div className="hierarchy-map-head"><span className="eyebrow">MAPA HIERÁRQUICO</span><h2>Relação entre indicadores</h2><p>Clique em um indicador para visualizar seus detalhes.</p></div><div className="hierarchy-root">{seed.filter(item => !item.parent).map(parent => <div className="hierarchy-node-group" key={parent.code}><button className={`hierarchy-node ${parent.status}`} onClick={() => setDetail(parent)}><b>{parent.name}</b><small>Real {getValue(parent, 'real')} · Meta {getValue(parent, 'target')}</small></button>{seed.filter(child => child.parent === parent.code).map(child => <button className={`hierarchy-node child ${child.status}`} key={child.code} onClick={() => setDetail(child)}><b>{child.name}</b><small>Real {getValue(child, 'real')} · Meta {getValue(child, 'target')}</small></button>)}</div>)}</div></section> : <section className="map-sheet"><div className="map-sheet-head"><div><span className="eyebrow">PLANILHA / FAROL</span><h2>Indicadores da Unidade Gerencial</h2></div><span>Período selecionado: <b>{selectedMonth} 2026</b></span></div><div className="map-sheet-scroll"><table className="map-grid refined-map"><thead><tr><th>Indicador</th><th>Usuários</th><th>Real</th><th>Meta</th>{months.map(month => <th key={month} className={month === selectedMonth ? 'selected-month' : ''}><button className="month-button" onClick={() => setSelectedMonth(month)}>{month}</button></th>)}<th>YTD</th><th>Ações</th></tr></thead><tbody>{perspectives.map(([code, label, color]) => { const open = expandedGroups.includes(code); const group = indicatorRows(code); return <React.Fragment key={code}><tr className="map-group"><th colSpan={18}><button className="group-toggle" onClick={() => setExpandedGroups(current => open ? current.filter(value => value !== code) : [...current, code])}><span>{open ? '−' : '+'}</span><i style={{ background: color }}/>{label}<small>({seed.filter(item => item.perspective === code).length})</small></button></th></tr>{open && group.map((item, index) => <tr key={item.code}><td><button className="map-indicator-link" onClick={() => setDetail(item)}><span>{item.parent ? '↳' : '▾'}</span><strong>{item.name}</strong><small>{item.code} · {item.owner}</small></button></td><td><AvatarStack names={item.viewers}/></td><td className="map-value">{getValue(item, 'real')}</td><td className="map-value">{getValue(item, 'target')}</td>{months.map((month, monthIndex) => <td className={`map-light ${month === selectedMonth ? 'selected-month' : ''}`} key={month}><span className={`traffic-symbol ${shape(item, index + monthIndex)}`}>{shape(item, index + monthIndex) === 'red' ? '▲' : shape(item, index + monthIndex) === 'yellow' ? '■' : '●'}</span></td>)}<td className="map-ytd"><b>{getValue(item, 'real')}</b><small>meta {getValue(item, 'target')}</small></td><td><div className="map-actions"><button title="Visualizar" onClick={() => setDetail(item)}><Search size={13}/></button><button title="Editar"><Edit3 size={13}/></button></div></td></tr>)}</React.Fragment>})}</tbody></table></div></section>}{detail && <IndicatorSide item={detail} onClose={() => setDetail(null)}/>}</Screen>
}

function MapViewRefined() {
	const [selectedMonth, setSelectedMonth] = useState('Jul')
	const [expanded, setExpanded] = useState<string[]>([])
	const [detail, setDetail] = useState<Indicator | null>(null)
	const [mode, setMode] = useState<'lista'|'hierarquia'>('lista')
	const real = (item: Indicator) => { const monthIndex = months.indexOf(selectedMonth); const values = item.status === 'red' ? ['89%','91%','92%','90%','88%','91%','91%','87%','90%','92%','91%','89%'] : item.status === 'yellow' ? ['94%','93%','95%','94%','92%','94%','94%','93%','95%','94%','94%','92%'] : ['100%','98%','101%','100%','99%','100%','100%','100%','102%','100%','100%','99%']; return values[monthIndex] }
	const target = (item: Indicator) => { const monthIndex = months.indexOf(selectedMonth); const values = item.status === 'red' ? ['95%','95%','95%','95%','95%','95%','95%','95%','95%','95%','95%','95%'] : item.status === 'yellow' ? ['96%','96%','96%','96%','96%','96%','96%','96%','96%','96%','96%','96%'] : ['100%','100%','100%','100%','100%','100%','100%','100%','100%','100%','100%','100%']; return values[monthIndex] }
	const statusFor = (item: Indicator, index: number): Status => item.status === 'red' ? 'red' : item.status === 'yellow' || index % 5 === 3 ? 'yellow' : 'green'
	const symbolFor = (status: Status) => status === 'red' ? '▲' : status === 'yellow' ? '■' : status === 'green' ? '●' : '◆'
	const toggleMode = () => setMode(current => current === 'lista' ? 'hierarquia' : 'lista')
	return <Screen title="Mapa de indicadores" subtitle="Acompanhe Real, Meta, farol mensal e YTD por indicador."><div className="map-sheet-toolbar"><div className="map-mode"><button className="selected">Lista de indicadores</button><button>Mapa hierárquico</button></div><Btn primary><Plus size={15}/> Novo indicador</Btn></div><section className="map-sheet"><div className="map-sheet-head"><div><span className="eyebrow">PLANILHA / FAROL</span><h2>Indicadores da Unidade Gerencial</h2></div><span>Período selecionado: <b>{selectedMonth} 2026</b></span></div><div className="map-sheet-scroll"><table className="map-grid refined-map"><thead><tr><th>Indicador</th><th>Usuários</th><th>Real</th><th>Meta</th>{months.map(month=><th key={month} className={month===selectedMonth?'selected-month':''}><button className="month-button" onClick={()=>setSelectedMonth(month)}>{month}</button></th>)}<th>YTD</th><th>Ações</th></tr></thead><tbody>{perspectives.map(([code,label,color])=>{const group=seed.filter(item=>item.perspective===code);const isExpanded=expanded.includes(code);return <React.Fragment key={code}><tr className="map-group"><th colSpan={18}><button className="group-toggle" onClick={()=>setExpanded(current=>isExpanded?current.filter(value=>value!==code):[...current,code])}><span>{isExpanded?'−':'+'}</span><i style={{background:color}}/>{label}<small>({group.length})</small></button></th></tr>{isExpanded&&group.map((item,index)=><tr key={item.code}><td><button className="map-indicator-link" onClick={()=>setDetail(item)}><span>{item.parent?'↳':'▾'}</span><strong>{item.name}</strong><small>{item.code} · {item.owner}</small></button></td><td><AvatarStack names={item.viewers}/></td><td className="map-value">{real(item)}</td><td className="map-value">{target(item)}</td>{months.map((month,monthIndex)=>{const status=statusFor(item,index+monthIndex);return <td className={`map-light ${month===selectedMonth?'selected-month':''}`} key={month}><span className={`traffic-symbol ${status}`}>{symbolFor(status)}</span></td>})}<td className="map-ytd"><b>{real(item)}</b><small>meta {target(item)}</small></td><td><div className="map-actions"><button title="Visualizar" onClick={()=>setDetail(item)}><Search size={13}/></button><button title="Editar"><Edit3 size={13}/></button></div></td></tr>)}</React.Fragment>})}</tbody></table></div></section>{detail&&<IndicatorSide item={detail} onClose={()=>setDetail(null)}/>}</Screen>
}

type View = 'home'|'mbi'|'mbo'|'mapa'|'farol'|'pdca'|'projetos'|'usuarios'|'organograma'
type Status = 'positive'|'green'|'yellow'|'red'
type Indicator = { code:string; name:string; perspective:string; owner:string; transmitter:string; viewers:string[]; target:string; result:string; status:Status; parent?:string; calc?:string }
const perspectives = [['FINANCIAL_RESILIENCE','Financial resilience','#070633'],['BUSINESS_GROWTH','Business growth','#070633'],['EFFICIENCY','Efficiency','#070633'],['CUSTOMER','Customer','#070633'],['EMPLOYEE','Employee','#070633'],['STABLE_BUSINESS','Stable business','#070633']] as const
const users = ['Cassiano Souza','Emanuel Caxias','Nicolle Gluck','Alexandre Silva','Gabrielle Leocádio','Jacqueline Araujo','Leticia Silva','Nicolas Cavalcante','Nohara Ken','Mauro Iwamura']
const avatar = (u:string) => `https://i.pravatar.cc/80?u=${encodeURIComponent(u)}`
const seed:Indicator[] = [
 {code:'FIN-001',name:'CAPEX overall',perspective:'FINANCIAL_RESILIENCE',owner:'Mauro Iwamura',transmitter:'Cassiano Souza',viewers:['Emanuel Caxias','Nicolle Gluck','Alexandre Silva','Diretoria'],target:'R$ 48,0 mi',result:'R$ 45,2 mi',status:'positive',calc:'Soma'},
 {code:'FIN-001.1',name:'CAPEX planejamento industrial',perspective:'FINANCIAL_RESILIENCE',owner:'Cassiano Souza',transmitter:'Gabrielle Leocádio',viewers:['Emanuel Caxias','Nicolle Gluck'],target:'R$ 28,0 mi',result:'R$ 27,4 mi',status:'positive',parent:'FIN-001'},
 {code:'FIN-001.2',name:'CAPEX engenharia de produto',perspective:'FINANCIAL_RESILIENCE',owner:'Gabrielle Leocádio',transmitter:'Alexandre Silva',viewers:['Cassiano Souza','Nohara Ken'],target:'R$ 20,0 mi',result:'R$ 17,8 mi',status:'yellow',parent:'FIN-001'},
 {code:'FIN-002',name:'Receita líquida',perspective:'FINANCIAL_RESILIENCE',owner:'Helio Ninomiya',transmitter:'Mauro Iwamura',viewers:['Diretoria','Emanuel Caxias'],target:'R$ 210 mi',result:'R$ 214 mi',status:'positive'},
 {code:'GRO-001',name:'Market share South America',perspective:'BUSINESS_GROWTH',owner:'Valmir Fernandez',transmitter:'Nohara Ken',viewers:['Mauro Iwamura'],target:'22,0%',result:'20,8%',status:'yellow'},
 {code:'EFF-001',name:'Entrega no prazo',perspective:'EFFICIENCY',owner:'Alexandre Silva',transmitter:'Nicolle Gluck',viewers:['Cassiano Souza'],target:'95%',result:'91%',status:'red'},
 {code:'CUS-001',name:'NPS clientes',perspective:'CUSTOMER',owner:'Jacqueline Araujo',transmitter:'Leticia Silva',viewers:['Diretoria'],target:'75 pts',result:'78 pts',status:'positive'},
 {code:'EMP-001',name:'Horas de treinamento',perspective:'EMPLOYEE',owner:'Leticia Silva',transmitter:'Nicolas Cavalcante',viewers:['RH'],target:'420 h',result:'395 h',status:'yellow'},
 {code:'STA-001',name:'Índice de continuidade operacional',perspective:'STABLE_BUSINESS',owner:'Nohara Ken',transmitter:'Emanuel Caxias',viewers:['Diretoria'],target:'99,5%',result:'99,8%',status:'positive'},
]
const months = ['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez']
function MapView() { const [selectedMonth,setSelectedMonth]=useState('Jul');const [mode,setMode]=useState<'lista'|'hierarquia'>('lista');const [items]=useState(seed);const [detail,setDetail]=useState<Indicator|null>(null);const monthIndex=months.indexOf(selectedMonth);const score=(item:Indicator,index:number)=>item.status==='red'?'red':item.status==='yellow'||index%5===3?'yellow':'green';const monthValue=(item:Indicator,index:number)=>item.status==='red'&&index%3===0?'▲':score(item,index)==='yellow'?'■':'●';const selectedReal=(item:Indicator)=>item.status==='red'?'91%':item.status==='yellow'?'94%':'100%';const selectedTarget=(item:Indicator)=>item.status==='red'?'95%':item.status==='yellow'?'96%':'100%';return <Screen title="Mapa de indicadores" subtitle="Acompanhe Real, Meta, farol mensal e YTD por indicador."><div className="map-sheet-toolbar"><div className="map-mode"><button className={mode==='lista'?'selected':''} onClick={()=>setMode('lista')}>Lista de indicadores</button><button className={mode==='hierarquia'?'selected':''} onClick={()=>setMode('hierarquia')}>Mapa hierárquico</button></div><label>Mês<select value={selectedMonth} onChange={event=>setSelectedMonth(event.target.value)}>{months.map(month=><option key={month}>{month}</option>)}</select></label><Btn primary><Plus size={15}/> Novo indicador</Btn></div><section className="map-sheet"><div className="map-sheet-head"><div><span className="eyebrow">PLANILHA / FAROL</span><h2>Indicadores da Unidade Gerencial</h2></div><span>Período selecionado: <b>{selectedMonth} 2026</b></span></div><div className="map-sheet-scroll"><table className="map-grid"><thead><tr><th>Indicador</th><th>Usuários</th><th>Real</th><th>Meta</th>{months.map(month=><th className={month===selectedMonth?'selected-month':''} key={month}>{month}</th>)}<th>YTD</th><th>Ações</th></tr></thead><tbody>{perspectives.map(perspective=>{const group=items.filter(item=>item.perspective===perspective[0]);return <React.Fragment key={perspective[0]}><tr className="map-group"><th colSpan={17}><span style={{background:perspective[2]}}/>{perspective[1]} <small>({group.length})</small></th></tr>{group.filter(item=>mode==='lista'||!item.parent).map((item,index)=><tr key={item.code}><td><button className="map-indicator-link" onClick={()=>setDetail(item)}><span>{item.parent?'↳':'▾'}</span><strong>{item.name}</strong><small>{item.code} · {item.owner}</small></button></td><td><AvatarStack names={item.viewers}/></td><td className="map-value">{selectedReal(item)}</td><td className="map-value">{selectedTarget(item)}</td>{months.map((month,monthPosition)=><td className={`map-light ${month===selectedMonth?'selected-month':''}`} key={month}><span className={`traffic ${score(item,index+monthPosition)}`} title={`${month}: ${monthValue(item,index+monthPosition)}`}>{monthValue(item,index+monthPosition)}</span></td>)}<td className="map-ytd"><b>{selectedReal(item)}</b><small>meta {selectedTarget(item)}</small></td><td><div className="map-actions"><button title="Visualizar" onClick={()=>setDetail(item)}><Search size={13}/></button><button title="Editar"><Edit3 size={13}/></button></div></td></tr>)}</React.Fragment>})}</tbody></table></div></section>{detail&&<IndicatorSide item={detail} onClose={()=>setDetail(null)}/>}</Screen> }
function PreviewTable({title,rows}:{title:string;rows:string[][]}) { return <div className="preview-table-wrap"><h3>{title}</h3><table className="preview-table"><thead><tr><th></th>{months.map(m=><th key={m}>{m}</th>)}</tr></thead><tbody>{rows.map(row=><tr key={row[0]}><th>{row[0]}</th>{row.slice(1).map((value,index)=><td key={`${row[0]}-${index}`}>{value}</td>)}</tr>)}</tbody></table></div> }
function IndicatorPreview({item,onClose}:{item:Indicator;onClose:()=>void}) { const rows=[['Last Year','83,00%','88,00%','70,00%','90,00%','43,00%','73,00%','41,00%','43,00%','74,00%','90,00%','74,00%','56,00%'],['Target','91,00%','91,00%','91,00%','91,00%','91,00%','91,00%','92,00%','92,00%','92,00%','92,00%','92,00%','92,00%'],['Result','69,00%','73,00%','76,00%','75,00%','69,00%','75,00%','57,00%','-','-','-','-','-'],['% Target','75,82%','80,22%','83,52%','82,42%','75,82%','82,42%','61,96%','0%','0%','0%','0%','0%']];return <div className="preview-overlay"><section className="indicator-preview"><header><div className="preview-title"><span className="preview-info">i</span><div><h2>{item.name}</h2><p>{item.perspective.replaceAll('_',' ')}</p></div></div><button className="preview-close" onClick={onClose}><X size={17}/></button></header><div className="preview-body"><aside className="preview-meta"><p><b>Description</b>{item.name}</p><p><b>Calculation Formula</b>Compliance rate for {item.name.toLowerCase()}</p><p><b>Calculation Type (YTD)</b>Current month</p><p><b>Strategic Perspective</b>{item.perspective.replaceAll('_',' ')}</p><p><b>Polarity</b>{item.status==='red'?'Lower is better':'Higher is better'}</p><p><b>Reporting Frequency</b>Monthly</p></aside><div className="preview-data"><PreviewTable title="Current Month" rows={rows}/><PreviewTable title="Accumulated" rows={rows}/><div className="preview-chart"><div className="chart-legend"><span>Last Year</span><span>Result</span><span>Target</span></div><div className="chart-bars">{months.map((m,index)=><div className="chart-column" key={m}><div className="bars"><i className="bar last" style={{height:`${[72,76,62,80,39,66,37,39,66,80,66,50][index]}%`}}/><i className="bar result" style={{height:`${[59,63,66,64,59,64,49,5,5,5,5,5][index]}%`}}/></div><small>{m}</small></div>)}</div></div></div></div></section></div> }
function MBIWithPreview() { const [detail,setDetail]=useState<Indicator|null>(null);return <div className="mbi-preview-host" onClick={event=>{const target=event.target as HTMLElement;const cell=target.closest('.mbi-table td:first-child');if(cell){const name=cell.textContent?.split(' · ')[0].trim();const item=seed.find(indicator=>name?.startsWith(indicator.name));if(item)setDetail(item)}}}><MBI/>{detail&&<IndicatorPreview item={detail} onClose={()=>setDetail(null)}/>}</div> }
function Dot({status}:{status:Status}) { return <span className={`status-dot ${status}`} /> }
function Btn({children,primary=false,onClick}:{children:React.ReactNode;primary?:boolean;onClick?:()=>void}) { return <button onClick={onClick} className={primary?'btn primary':'btn'}>{children}</button> }
function Screen({title,subtitle,children}:{title:string;subtitle:string;children:React.ReactNode}) { return <><div className="screen-head"><div><span className="eyebrow">MANAGEMENT BUSINESS SYSTEM</span><h1>{title}</h1><p>{subtitle}</p></div><Btn><CalendarDays size={15}/> 2026 <ChevronDown size={14}/></Btn></div>{children}</> }
function Welcome({onStart}:{onStart:()=>void}) { return <div className="welcome"><div className="wave-brand"><strong>YAMAHA</strong><span>Management Business System</span></div><div className="welcome-card"><div><span className="eyebrow">STRATEGIC MANAGEMENT</span><h1>Gestão por<br/><b>estratégia</b></h1><p>Conecte metas, indicadores, projetos e pessoas em uma única visão de negócio.</p><Btn primary onClick={onStart}>Começar <ChevronRight size={16}/></Btn></div><div className="welcome-illustration"><BarChart3 size={110}/><Target size={76}/></div></div></div> }
function Sidebar({view,setView}:{view:View;setView:(v:View)=>void}) { const [collapsed,setCollapsed]=useState(false);const items:[View,string,React.ElementType][]=[['home','Início',HomeIcon],['mbi','MBI',Activity],['mbo','MBO',Target],['mapa','Mapa de indicadores',GitBranch],['farol','Planilha / Farol',BarChart3],['pdca','Soluções de problemas',ClipboardCheck],['projetos','Projetos',FolderKanban],['usuarios','Usuários',Users],['organograma','Organograma',GitBranch]]; return <aside className={`side ${collapsed?'collapsed':''}`}><div className="side-brand"><div className="side-logo">Y<span>MBS</span></div><button className="side-toggle" onClick={()=>setCollapsed(value=>!value)} aria-label={collapsed?'Expandir navegação':'Condensar navegação'}><Menu size={17}/></button></div><nav>{items.map(([key,label,Icon])=><button key={key} className={view===key?'active':''} onClick={()=>setView(key)} title={label}><Icon size={20}/><span>{label}</span></button>)}</nav><div className="side-bottom"><button><Bell size={20}/><span>Alertas</span></button></div></aside> }
function Top({view,setView}:{view:View;setView:(v:View)=>void}) { return <header className="top"><button className="mobile-menu"><Menu size={19}/></button><div className="top-title">MBS <span>/ {view.toUpperCase()}</span></div><div className="top-actions"><div className="top-search"><Search size={15}/><input placeholder="Pesquisar"/></div><span className="year">2026 <ChevronDown size={14}/></span><button className="avatar" onClick={()=>setView('usuarios')}>EL</button><div><b>Emanuel Lacerda</b><small>Administrador</small></div></div></header> }
function Home({setView}:{setView:(v:View)=>void}) { return <div className="home-view"><div className="home-hero"><span className="eyebrow">BEM-VINDO AO MBS</span><h1>Olá, Emanuel.<br/><b>O que vamos alcançar hoje?</b></h1><p>Tenha uma visão rápida da performance e acesse suas rotinas estratégicas.</p></div><div className="quick-grid"><button onClick={()=>setView('mbi')}><Activity/><b>Acompanhamento MBI</b><small>Veja seus indicadores mensais</small></button><button onClick={()=>setView('mbo')}><Target/><b>MBO / PLR</b><small>Metas semestrais</small></button><button onClick={()=>setView('mapa')}><GitBranch/><b>Mapa estratégico</b><small>Relações de causa e efeito</small></button><button onClick={()=>setView('farol')}><BarChart3/><b>Planilha / Farol</b><small>Valores mensais e YTD</small></button></div><div className="home-panels"><section className="card"><h2>Resumo da organização</h2><div className="metrics"><div><strong>72%</strong><span>Indicadores na meta</span></div><div><strong>08</strong><span>Projetos em andamento</span></div><div><strong>05</strong><span>Pontos de atenção</span></div></div></section><section className="card"><h2>Próximas atividades</h2>{['Fechamento MBI · 18 Dez','Comitê de resultados · 20 Dez','Revisão de metas · 23 Dez'].map(x=><div className="activity-row" key={x}><CalendarDays size={15}/>{x}<ChevronRight size={14}/></div>)}</section></div></div> }
function MBI() { const [month,setMonth]=useState('Jul');const [selectedMember,setSelectedMember]=useState('Cassiano Souza');const mainIndicators=seed.slice(0,6);const team=['Cassiano Souza','Emanuel Caxias','Nicolle Gluck','Alexandre Silva'];const values=[['-R$ 47,00 MI','R$ 210,43 MI','-R$ 4,38 MI','-R$ 13,34 MI'],['R$ 43,22 MI','R$ 57,59 MI','R$ 81,11 MI','R$ 54,95 MI'],['91,00%','77,34%','70,00%','77,29%'],['-','11.089','11.112','9.791'],['28.970','33.552','33.699','29.413'],['13,44%','14,06%','14,06%','13,89%']];const memberIndicators=(member:string)=>seed.filter(i=>i.owner===member||i.viewers.includes(member)).slice(0,5);return <Screen title="Acompanhamento MBI" subtitle="Indicadores mensais do usuário e da estrutura sob sua responsabilidade."><div className="mbi-toolbar"><div className="mbi-filters"><label>Ano<select><option>2026</option><option>2025</option></select></label><label>Mês<select value={month} onChange={e=>setMonth(e.target.value)}>{months.map(m=><option key={m}>{m}</option>)}</select></label><span className="mbi-period">Período ativo: <b>{month} 2026</b></span></div><Btn>Exportar</Btn></div><section className="mbi-board"><div className="mbi-board-head"><div><span className="eyebrow">VISÃO DO USUÁRIO</span><h2>Emanuel Lacerda <small>· MBI mensal</small></h2></div><div className="mbi-progress"><strong>4 / 6</strong><span>indicadores preenchidos</span><i><b style={{width:'66%'}} /></i></div></div><div className="mbi-table-scroll"><table className="mbi-table"><thead><tr><th rowSpan={2}>Indicador</th><th rowSpan={2}>Polaridade</th><th rowSpan={2}>Unidade</th><th colSpan={4}>Monthly results</th><th colSpan={4}>Year to date</th></tr><tr><th>Last Year</th><th>Original Target</th><th>Revised Target</th><th>Result</th><th>Last Year</th><th>Original Target</th><th>Revised Target</th><th>Result</th></tr></thead><tbody>{mainIndicators.map((item,index)=><tr key={item.code}><td><b>{item.name}</b><small>{item.code} · {item.perspective}</small></td><td><span className={`polarity ${item.status==='red'?'down':''}`}>{item.status==='red'?'↓':'↑'}</span></td><td>{item.name.includes('%')?'%':'R$'}</td>{values[index].map((value,valueIndex)=><td key={`${item.code}-${valueIndex}`}>{value}</td>)}{values[index].map((value,valueIndex)=><td key={`${item.code}-ytd-${valueIndex}`}>{valueIndex===3?item.result:value}</td>)}<td><Dot status={item.status}/></td></tr>)}</tbody></table></div></section><section className="mbi-structure"><div className="mbi-section-title"><div><span className="eyebrow">HIERARQUIA</span><h2>Organization</h2></div><span>{team.length} usuários relacionados</span></div><div className="mbi-user-grid">{team.map(member=>{const indicators=memberIndicators(member);return <button className={`mbi-user-card ${selectedMember===member?'selected':''}`} key={member} onClick={()=>setSelectedMember(member)}><div className="mbi-user-head"><img src={avatar(member)} alt=""/><div><b>{member}</b><small>{member==='Cassiano Souza'?'COMMERCIAL & MKT':member==='Emanuel Caxias'?'INDUSTRIAL':'FINANCE'}</small></div><strong>{Math.round((indicators.filter(i=>i.status==='positive').length/Math.max(indicators.length,1))*100)}%</strong></div><div className="mbi-mini-list">{indicators.map(item=><span key={item.code}><em>{item.name}</em><b>{item.result}</b><Dot status={item.status}/></span>)}</div><footer><span>{indicators.length} indicadores</span><ChevronRight size={14}/></footer></button>})}</div><div className="mbi-selection"><span>Usuário selecionado</span><b>{selectedMember}</b><small>Selecione um cartão para acompanhar a hierarquia</small></div></section></Screen> }
function MBOScore({value,label}:{value:string;label:string}) { return <div className="mbo-score"><div className="mbo-ring" style={{'--score':`${parseFloat(value.replace(',','.'))}%`} as React.CSSProperties}><strong>{value}</strong></div><span>{label}</span></div> }
function MBO() { const rows=seed.slice(0,9);return <Screen title="MBO / PLR" subtitle="Goal comparison · acompanhamento semestral de metas e projetos."><div className="mbo-shell"><div className="mbo-context"><div><span className="eyebrow">GOAL COMPARISON</span><b>Year</b><span>2026 GOALS</span></div><div className="mbo-context-stat"><strong>9</strong><span>Indicadores</span><strong>1</strong><span>Projetos</span></div><div className="mbo-context-stat"><strong>100</strong><span>Total Weight</span></div><MBOScore value="91,93%" label="Half Result · 01st half"/><div className="mbo-context-stat"><strong>10</strong><span>Indicadores</span><strong>1</strong><span>Projetos</span></div><div className="mbo-context-stat"><strong>100</strong><span>Total Weight</span></div><MBOScore value="0,00%" label="Half Result · 02nd half"/></div><section className="mbo-panel"><div className="mbo-panel-title"><span>◉</span><h2>INDICATORS</h2><div className="mbo-half-label">2026 GOALS · 01st half</div><div className="mbo-half-label">2026 GOALS · 02nd half</div></div><div className="mbo-table-scroll"><table className="mbo-table"><thead><tr><th>Indicator</th><th>Polarity</th><th>Unit</th><th>Target</th><th>Result</th><th>%/Target</th><th>W. (%)</th><th>Trigger</th><th>Score</th><th>Target</th><th>Result</th><th>%/Target</th><th>W. (%)</th><th>Trigger</th><th>Score</th></tr></thead><tbody>{rows.map((item,index)=><tr key={item.code}><td><b>{item.name}</b><small>{item.code} · {item.owner}</small></td><td><span className={`polarity ${item.status==='red'?'down':''}`}>{item.status==='red'?'↓':'↑'}</span></td><td>{item.name.includes('%')?'%':'R$'}</td><td>{item.target}</td><td>{item.result}</td><td>{item.status==='positive'?'100%':item.status==='yellow'?'95,97%':'85,99%'}</td><td>{index<4?'15%':'10%'}</td><td>80%</td><td className={`mbo-score-cell ${item.status}`}>{item.status==='red'?'0%':item.status==='yellow'?'95,97%':'100%'}</td><td>{item.target}</td><td>{index<2?item.result:'-'}</td><td>{index<2?'14,20%':'-'}</td><td>{index<4?'15%':'10%'}</td><td>80%</td><td className="mbo-score-cell empty">0%</td></tr>)}</tbody><tfoot><tr><td colSpan={6}></td><th>95%</th><td></td><th>87,93%</th><td colSpan={5}></td><th>0%</th></tr></tfoot></table></div></section><section className="mbo-panel mbo-projects"><div className="mbo-panel-title"><span>▣</span><h2>PROJECT</h2><div className="mbo-half-label">2026 PROJECTS · 01st half</div><div className="mbo-half-label">2026 PROJECTS · 02nd half</div></div><div className="mbo-table-scroll"><table className="mbo-project-table"><thead><tr><th>Project</th><th>Target</th><th>W. (%)</th><th>Result</th><th>W. (%)</th><th>Target</th><th>W. (%)</th><th>Result</th><th>W. (%)</th></tr></thead><tbody><tr><td>Inventory Control &amp; Risk Governance Stabilization 2026</td><td>Ensure completion of the first 149 countermeasures</td><td>5%</td><td className="project-result">80%</td><td>4,00%</td><td>Ensure completion of the remaining 150 countermeasures</td><td>5%</td><td>-</td><td>0,00%</td></tr></tbody><tfoot><tr><th colSpan={2}></th><th>5%</th><th></th><th>4%</th><th colSpan={2}></th><th></th><th>0%</th></tr></tfoot></table></div></section></div></Screen> }
function AvatarStack({names}:{names:string[]}) { return <div className="avatar-stack">{names.slice(0,3).map(u=><img key={u} src={avatar(u)} alt={u} title={u}/>)}{names.length>3&&<span>+{names.length-3}</span>}</div> }
function IndicatorModal({initial,onClose,onSave}:{initial?:Indicator;onClose:()=>void;onSave:(i:Indicator)=>void}) { const [name,setName]=useState(initial?.name||'');const [code,setCode]=useState(initial?.code||'IND-010');const [perspective,setPerspective]=useState(initial?.perspective||'FINANCIAL_RESILIENCE');const [owner,setOwner]=useState(initial?.owner||users[0]);const [transmitter,setTransmitter]=useState(initial?.transmitter||users[1]);const [target,setTarget]=useState(initial?.target||'');const [parent,setParent]=useState(initial?.parent||'');const [calc,setCalc]=useState(initial?.calc||'Média');const [selected,setSelected]=useState(initial?.viewers||users.slice(0,3));return <div className="modal-wrap"><div className="modal card wide"><button className="close" onClick={onClose}><X size={18}/></button><span className="eyebrow">{initial?'EDITAR INDICADOR':'NOVO INDICADOR'}</span><h2>{initial?'Editar indicador':'Criar indicador estratégico'}</h2><div className="form-grid"><label>Nome do indicador *<input value={name} onChange={e=>setName(e.target.value)}/></label><label>Código *<input value={code} onChange={e=>setCode(e.target.value)}/></label><label>Perspectiva *<select value={perspective} onChange={e=>setPerspective(e.target.value)}>{perspectives.map(p=><option key={p[0]} value={p[0]}>{p[1]}</option>)}</select></label><label>Meta<input value={target} onChange={e=>setTarget(e.target.value)} placeholder="Ex.: R$ 48,0 mi"/></label><label>Parent indicator<select value={parent} onChange={e=>setParent(e.target.value)}><option value="">Nenhum</option>{seed.filter(i=>i.code!==code).map(i=><option key={i.code} value={i.code}>{i.code} · {i.name}</option>)}</select></label><label>Tipo de cálculo<select value={calc} onChange={e=>setCalc(e.target.value)}><option>Média</option><option>Soma</option><option>Média ponderada</option></select></label><label>Responsável<select value={owner} onChange={e=>setOwner(e.target.value)}>{users.map(u=><option key={u}>{u}</option>)}</select></label><label>Usuário transmissor<select value={transmitter} onChange={e=>setTransmitter(e.target.value)}>{users.map(u=><option key={u}>{u}</option>)}</select></label></div><h3>Usuários que têm este indicador no card</h3><div className="user-cards">{users.slice(0,6).map(u=><button key={u} className={selected.includes(u)?'picked':''} onClick={()=>setSelected(x=>x.includes(u)?x.filter(v=>v!==u):[...x,u])}><img src={avatar(u)} alt=""/><b>{u}</b><small>{u.includes('Emanuel')?'TI e Estratégia':u.includes('Cassiano')?'Industrial':'Corporate Planning'}</small></button>)}</div><div className="modal-actions"><Btn onClick={onClose}>Cancelar</Btn><Btn primary onClick={()=>onSave({code,name:name||'Novo indicador',perspective,owner,transmitter,viewers:selected,target:target||'A definir',result:initial?.result||'0',status:initial?.status||'yellow',parent:parent||undefined,calc})}>Salvar indicador</Btn></div></div></div> }
function IndicatorSide({item,onClose}:{item:Indicator;onClose:()=>void}) { const [tab,setTab]=useState('Detalhes');return <div className="side-overlay"><aside className="indicator-side"><button className="close" onClick={onClose}><X size={18}/></button><div className="side-month">‹ Maio 2026 ›</div><h2>▲ {item.name}</h2><div className="side-kpis"><div className="red-kpi"><small>Real</small><b>{item.result}</b></div><div className="green-kpi"><small>YTD</small><b>{item.result}</b></div><div className="green-kpi"><small>Tendência</small><b>{item.target}</b></div></div><div className="side-tabs">{['Detalhes','Gráfico','Tarefas 7','Comentários 3','Soluções / Projetos 4'].map(t=><button className={tab===t?'active':''} key={t} onClick={()=>setTab(t)}>{t}</button>)}</div>{tab==='Detalhes'?<div className="side-content"><p><b>Responsável</b>{item.owner}</p><p><b>Transmissor</b>{item.transmitter}</p><p><b>Perspectiva</b>{item.perspective}</p><p><b>Meta do mês</b>{item.target}</p><h3>Usuários com indicador</h3>{item.viewers.map(u=><div className="side-user" key={u}><img src={avatar(u)} alt=""/>{u}<Dot status={item.status}/></div>)}</div>:<div className="side-content"><div className="fake-chart"><BarChart3 size={54}/><b>{tab}</b><small>Dados demonstrativos de 2026</small></div>{['Validar informação do mês','Plano de ação para reunião','Revisar projeção YTD'].map(x=><div className="task-row" key={x}>{x}<Btn>Iniciar</Btn></div>)}</div>}</aside></div> }
function MapViewLegacy() { const [items,setItems]=useState(seed);const [mode,setMode]=useState<'lista'|'hierarquia'>('lista');const [expanded,setExpanded]=useState(['FIN-001']);const [modal,setModal]=useState<Indicator|boolean|null>(null);const [detail,setDetail]=useState<Indicator|null>(null);const save=(i:Indicator)=>{setItems(x=>x.some(a=>a.code===i.code)?x.map(a=>a.code===i.code?i:a):[...x,i]);setModal(null)};return <Screen title="Mapa de indicadores" subtitle="Agrupe perspectivas, expanda indicadores derivados e visualize usuários relacionados."><div className="map-toolbar"><div className="half-tabs"><button className={mode==='lista'?'selected':''} onClick={()=>setMode('lista')}>Lista por perspectiva</button><button className={mode==='hierarquia'?'selected':''} onClick={()=>setMode('hierarquia')}>Mapa hierárquico</button></div><Btn primary onClick={()=>setModal(true)}><Plus size={15}/> Novo indicador</Btn></div>{mode==='lista'?<div className="indicator-table"><div className="indicator-head"><span>Indicador / hierarquia</span><span>Usuários</span><span>Responsável</span><span>Transmissor</span><span>Meta / Resultado</span><span>Ações</span></div>{perspectives.map(p=>{const group=items.filter(i=>i.perspective===p[0]);return <section key={p[0]}><div className="perspective-bar" style={{borderLeftColor:p[2]}}><b>{p[1]}</b><span>{group.length} indicadores</span></div>{group.filter(i=>!i.parent||expanded.includes(i.parent)).map(i=><div className={`indicator-row ${i.parent?'child':''}`} key={i.code}><button className="indicator-name" onClick={()=>setDetail(i)}><span className="expand" onClick={e=>{e.stopPropagation();if(items.some(a=>a.parent===i.code))setExpanded(x=>x.includes(i.code)?x.filter(v=>v!==i.code):[...x,i.code])}}>{items.some(a=>a.parent===i.code)?(expanded.includes(i.code)?'−':'+'):'·'}</span><Dot status={i.status}/><span><b>{i.name}</b><small>{i.code} · {i.calc||'Indicador'}</small></span></button><AvatarStack names={i.viewers}/><span>{i.owner}</span><span>{i.transmitter}</span><span>{i.result} / {i.target}<Dot status={i.status}/></span><span><button className="icon-button" onClick={()=>setModal(i)}><Edit3 size={14}/></button></span></div>)}</section>})}</div>:<div className="hierarchy-grid">{items.filter(i=>!i.parent).map(i=><button className="hierarchy-node" key={i.code} onClick={()=>setDetail(i)}><Dot status={i.status}/><b>{i.name}</b><small>{i.code} · {items.filter(x=>x.parent===i.code).length} indicadores derivados</small>{items.filter(x=>x.parent===i.code).map(c=><span key={c.code}>↳ {c.name}</span>)}</button>)}</div>}{modal&&<IndicatorModal initial={typeof modal==='object'?modal:undefined} onClose={()=>setModal(null)} onSave={save}/>} {detail&&<IndicatorSide item={detail} onClose={()=>setDetail(null)}/>}</Screen> }
function Farol() { const [perspective,setPerspective]=useState<string>(perspectives[0][0]);const rows=seed.filter(i=>i.perspective===perspective||perspective==='ALL');return <Screen title="Planilha / Farol" subtitle="Visualize YTD, valores mensais e o status de cada indicador."><div className="sheet-toolbar"><div className="perspective-tabs"><button className={perspective==='ALL'?'selected':''} onClick={()=>setPerspective('ALL')}>Todos</button>{perspectives.map(p=><button className={perspective===p[0]?'selected':''} key={p[0]} onClick={()=>setPerspective(p[0])}>{p[1].split(' ')[0]}</button>)}</div><Btn>Exportar XLSX</Btn></div><div className="sheet-card"><div className="sheet-head"><b>Indicador</b><b>YTD</b><b>Meta</b>{months.map(m=><b key={m}>{m}</b>)}</div>{rows.map(i=><div className="sheet-row" key={i.code}><div><button onClick={()=>{}} className="tree-inline">{i.parent?'↳':'▲'} {i.name}</button><small>{i.code} · {i.owner}</small></div><span>{i.result}</span><span>{i.target}</span>{months.map((m,idx)=><span key={m} className={`traffic ${idx%5===0?'red':idx%3===0?'yellow':'green'}`} title={`${m}: ${idx%5===0?'Fora da meta':'Dentro da meta'}`}>{idx%5===0?'▲':idx%3===0?'■':'●'}</span>)}</div>)}</div></Screen> }
function PDCA() { const [detail,setDetail]=useState(false);const [form,setForm]=useState(false);const [pdcas,setPdcas]=useState([{title:'Índice de ocupação de aeronaves abaixo da meta',owner:'Adriano Rodrigues',status:'Em execução',progress:39,indicator:'EFF-001'},{title:'Atraso na liberação de pedidos',owner:'Gabrielle Leocádio',status:'Em identificação',progress:18,indicator:'CUS-001'},{title:'Desvio de CAPEX engenharia de produto',owner:'Cassiano Souza',status:'Em análise',progress:62,indicator:'FIN-001.2'}]);const item=pdcas[0];return <Screen title="Soluções de problemas" subtitle="Lista de soluções e acompanhamento PDCA."><div className="toolbar"><span>Ações corretivas <ChevronDown size={14}/></span><span>44 Abertas</span><Btn primary onClick={()=>setForm(true)}><Plus size={15}/> Nova solução</Btn></div><div className="pdca-list">{pdcas.map((p,i)=><button key={p.title} onClick={()=>setDetail(true)}><Dot status={i===0?'red':i===1?'yellow':'green'}/><div><b>{p.title}</b><small>PDCA · {p.indicator} · Responsável: {p.owner}</small></div><span>{p.status}</span><span>{p.progress}%</span><ChevronRight size={16}/></button>)}</div>{detail&&<div className="modal-wrap"><div className="modal card detail-modal"><button className="close" onClick={()=>setDetail(false)}><X size={18}/></button><span className="eyebrow">PDCA · {item.status}</span><h2>{item.title}</h2><div className="progress-line"><span>Progresso</span><b>{item.progress}%</b><div><i style={{width:`${item.progress}%`}}/></div></div><div className="pdca-columns"><section><h3>Participantes</h3>{[item.owner,'Gerardo Estuáquio','Michele Maia'].map(u=><p key={u}><img src={avatar(u)} alt=""/> {u}</p>)}</section><section><h3>Plano de ações</h3>{['Validar informação do mês','Analisar causas do desvio','Implementar ação corretiva','Verificar resultado'].map((x,i)=><div className="task-row" key={x}><span>{i+1}. {x}</span><small>{i<2?'Concluída':'Em andamento'}</small></div>)}</section></div><h3>Indicadores vinculados</h3><div className="linked-indicator">EFF-001 · Entrega no prazo <Dot status="red"/> 91% / 95%</div><Btn primary onClick={()=>{setDetail(false);setForm(true)}}><Edit3 size={14}/> Editar solução</Btn></div></div>}{form&&<div className="modal-wrap"><div className="modal card wide"><button className="close" onClick={()=>setForm(false)}><X size={18}/></button><span className="eyebrow">PDCA · NOVA SOLUÇÃO</span><h2>Identificação do problema</h2><label>Descrição do problema *<textarea placeholder="Descreva o indicador fora da meta e o efeito observado."/></label><label>Bloqueio imediato do efeito<textarea placeholder="Registre a contenção imediata."/></label><div className="form-grid"><label>Indicador relacionado<select>{seed.map(i=><option key={i.code}>{i.code} · {i.name}</option>)}</select></label><label>Responsável<select>{users.map(u=><option key={u}>{u}</option>)}</select></label><label>Início previsto<input type="date" defaultValue="2026-08-01"/></label><label>Conclusão prevista<input type="date" defaultValue="2026-09-30"/></label></div><h3>Etapas iniciais do PDCA</h3><div className="check-grid"><label><input type="checkbox" defaultChecked/> Identificação</label><label><input type="checkbox"/> Análise de causa</label><label><input type="checkbox"/> Plano de ação</label><label><input type="checkbox"/> Verificação</label></div><div className="modal-actions"><Btn onClick={()=>setForm(false)}>Cancelar</Btn><Btn primary onClick={()=>{setForm(false);setPdcas(x=>[{title:'Novo desvio de indicador criado',owner:'Emanuel Lacerda',status:'Em identificação',progress:0,indicator:'EFF-001'},...x])}}>Criar solução</Btn></div></div></div>}</Screen> }
function Projetos() { const [selected,setSelected]=useState<string|null>(null);const projects=[['Inventory Control & Risk Governance Stabilization','Cassiano Souza','72%'],['Digital Customer Journey 2026','Jacqueline Araujo','48%'],['Academia de Líderes Yamaha','Leticia Silva','34%']];return <Screen title="Projetos" subtitle="Conecte responsáveis, marcos, indicadores, atividades e cronogramas."><div className="toolbar"><span>Todos os projetos <ChevronDown size={14}/></span><Btn primary><Plus size={15}/> Novo projeto</Btn></div><div className="project-grid">{projects.map(([name,owner,progress])=><section className="card project-card" key={name}><div className="project-top"><FolderKanban size={18}/><Dot status="green"/></div><h2>{name}</h2><p>Responsável: <b>{owner}</b></p><div className="bar"><i style={{width:progress}}/></div><div className="project-meta"><span>Marcos <b>4</b></span><span>Atividades <b>12</b></span><span>Indicadores <b>2</b></span></div><Btn onClick={()=>setSelected(name)}>Abrir projeto <ChevronRight size={14}/></Btn></section>)}</div>{selected&&<div className="modal-wrap"><div className="modal card wide project-detail"><button className="close" onClick={()=>setSelected(null)}><X size={18}/></button><span className="eyebrow">PROJETO · EM EXECUÇÃO</span><h2>{selected}</h2><p>Responsável: <b>Cassiano Souza</b> · 72% concluído · 01 Abr — 31 Dez 2026</p><div className="project-detail-grid"><section><h3>Indicadores relacionados</h3>{seed.slice(0,3).map(i=><div className="linked-indicator" key={i.code}>{i.name}<Dot status={i.status}/></div>)}</section><section><h3>Marcos e atividades</h3>{['Diagnóstico e baseline','Aprovação do plano','Implementação da solução','Validação de resultados'].map((x,i)=><div className="gantt-row" key={x}><span><Dot status={i<2?'green':i===2?'yellow':'red'}/>{x}</span><div><i style={{left:`${i*20}%`,width:`${30+i*4}%`}}/></div><small>{i<2?'Concluído':i===2?'Em andamento':'Pendente'}</small></div>)}</section></div><h3>Timeline Gantt</h3><div className="gantt-calendar">{months.slice(0,9).map(m=><span key={m}>{m}</span>)}</div></div></div>}</Screen> }
function Usuarios() { const [selected,setSelected]=useState(0);return <Screen title="Team Management" subtitle="Configure reporting structure and delegation permissions."><div className="users-layout"><section className="user-list card"><div className="user-search"><Search size={16}/><input placeholder="Search employees..."/></div>{users.map((u,i)=><button className={selected===i?'selected':''} key={u} onClick={()=>setSelected(i)}><span className="user-avatar"><img src={avatar(u)} alt=""/></span><div><b>{u}</b><small>{i%2?'INDUSTRIAL PLANNING':'INFORMATION TECHNOLOGY'}</small></div>{i<5&&<em>Admin</em>}</button>)}</section><section className="user-detail card"><div className="profile-head"><span className="profile-avatar"><img src={avatar(users[selected])} alt=""/></span><div><h2>{users[selected]}</h2><small>INDUSTRIAL PLANNING · STRATEGY ANALYST</small></div></div><div className="form-grid">{['Name','Department','Position','Report manager'].map(x=><label key={x}>{x} *<input defaultValue={x==='Name'?users[selected]:x==='Department'?'INDUSTRIAL PLANNING':x==='Position'?'STRATEGY ANALYST':'Nohara Ken'}/></label>)}</div><Btn primary>Save Changes</Btn></section></div></Screen> }
function Organograma() { return <Screen title="Organograma" subtitle="Visualize a estrutura de reporte e navegue pela empresa."><div className="org-toolbar"><div className="user-search"><Search size={16}/><input placeholder="Procurar pessoas"/></div><Btn>Minha estrutura</Btn><Btn>Empresa inteira</Btn></div><div className="org-canvas"><div className="org-root"><span className="profile-avatar"><img src={avatar('Mauro Iwamura')} alt=""/></span><b>Mauro Iwamura</b><small>President</small></div><div className="org-connector"/><div className="org-level"><div className="org-manager"><span className="profile-avatar">NK</span><b>Nohara Ken</b><small>Executive director</small></div><div className="org-children">{users.slice(0,6).map(u=><div className="org-person" key={u}><span className="profile-avatar"><img src={avatar(u)} alt=""/></span><div><b>{u}</b><small>Industrial planning</small></div><ChevronRight size={15}/></div>)}</div></div></div></Screen> }
export default function Page() { const [started,setStarted]=useState(false);const [view,setView]=useState<View>('home');const content=view==='home'?<Home setView={setView}/>:view==='mbi'?<MBIWithPreview/>:view==='mbo'?<MBO/>:view==='mapa'?<MapViewFinal/>:view==='farol'?<Farol/>:view==='pdca'?<PDCA/>:view==='projetos'?<Projetos/>:view==='usuarios'?<Usuarios/>:<Organograma/>;if(!started)return <Welcome onStart={()=>setStarted(true)}/>;return <main className="app-shell"><Sidebar view={view} setView={setView}/><div className="workspace"><Top view={view} setView={setView}/><div className="content">{content}</div></div></main> }
